effect.shader:
void main(){
vec2 uv=acScreenNorm,p=uv-0.5; float c=cos(direction),s=sin(direction);
mat2 r=mat2(c,-s,s,c); vec2 a=r*p;
float theta=a.x/max(radius,0.01)*curve*1.5707963;
float z=(1.0-cos(theta))*radius;
vec2 w=vec2(sin(theta)*radius/max(abs(curve)*1.5707963,0.001),a.y/(1.0+z*perspective));
if(curve<0.0) w.x=-w.x;
vec2 q=mat2(c,s,-s,c)*w+0.5;
float valid=step(0.0,q.x)*step(q.x,1.0)*step(0.0,q.y)*step(q.y,1.0);
vec4 src=texture2DCv(inputImg.texture,uv),dst=texture2DCv(inputImg.texture,clamp(q,0.0,1.0));
float highlight=pow(max(cos(theta),0.0),8.0);
dst.rgb*=0.58+0.42*max(cos(theta),0.0); dst.rgb+=highlight*specular;
gl_FragColor=mix(src,dst,mixAmount*valid);
}
